// Gaz alarmı: MQ-2 değeri eşiği geçince buzzer öter, kırmızı LED yanar.
const int GAZ_PIN = A0;
const int BUZZER_PIN = 8;
const int LED_PIN = 9;
const int ESIK = 400;                       // 0-1023; temiz havadaki değerin 100-150 üstü
const unsigned long ISINMA_SURESI = 60000;  // ms; sensör ısınırken alarm verilmez

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.println("MQ-2 isiniyor, lutfen bekleyin...");
}

void loop() {
  int deger = analogRead(GAZ_PIN);
  Serial.print("Gaz: ");
  Serial.println(deger);

  // Isınma süresi: LED yavaşça yanıp söner, alarm yok.
  if (millis() < ISINMA_SURESI) {
    digitalWrite(LED_PIN, (millis() / 1000) % 2);
    delay(500);
    return;
  }

  if (deger > ESIK) {
    Serial.println("ALARM: gaz algilandi!");
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 2000, 250);  // kesik kesik öter
  } else {
    digitalWrite(LED_PIN, LOW);
    noTone(BUZZER_PIN);
  }
  delay(500);
}
